const callUserApi = async () => {
  // Check if options are already stored in localStorage with valid TTL
  const CACHE_TTL_MS = 2 * 60 * 1000; // 2 minutes
  const cachedOptions = localStorage.getItem('caseAssignedOptions');
  const cachedTs = parseInt(localStorage.getItem('caseAssignedOptions_ts') || '0', 10);
  const now = Date.now();
  if (cachedOptions && (now - cachedTs) < CACHE_TTL_MS) {
    component.data.values = JSON.parse(cachedOptions); // Use cached data
    console.log('Using cached caseAssignedOptions');
    return JSON.parse(cachedOptions);
  }

  // Get the authorization token from localStorage
  const token = localStorage.getItem('keycloakToken');

  if (!token) {
    console.error('Token not found in localStorage');
    return;
  }

  // Determine the base URL based on the environment (localhost or production)
  const baseUrl = window.location.hostname.includes('localhost')
    ? 'http://localhost:8081'
    : localStorage.getItem('baseUrl') || '';

  try {
    // Fetch users
    const response = await fetch(`${baseUrl}/case-definition/users`, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`
      }
    });

    // Fetch groups
  const responseGrp = await fetch(`${baseUrl}/case-definition/groups`, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`
      }
    });

    // Validate both responses
    if (!response.ok) {
      throw new Error(`User API call failed with status: ${response.status}`);
    }

    if (!responseGrp.ok) {
      throw new Error(`Group API call failed with status: ${responseGrp.status}`);
    }

    // Parse response JSON
    const data = await response.json();      // users
    const grpData = await responseGrp.json(); // groups

    // Convert users to options
    const userOptions = data.map(user => ({
      label: user.userId,
      value: [user.emailId]
    }));

    // Convert groups to options
    const grpOptions = grpData.map(group => ({
      label: group.groupId,
      value: group.users.map(user => user.emailId)
    }));

    // Combine and return both
    const allOptions = [...userOptions, ...grpOptions];

    // Cache the result with timestamp
    localStorage.setItem('caseAssignedOptions', JSON.stringify(allOptions));
    localStorage.setItem('caseAssignedOptions_ts', String(Date.now()));

    return allOptions;
  } catch (error) {
    console.error('Error calling the User or Group API:', error);
  }
};

// Example usage of the function
callUserApi().then(userOptions => {
  if (userOptions) {
   component.data.values = userOptions.map(opt => ({ 
 label: opt.label, 
 value: { 
 email: opt.value,  
 label: opt.label 
  } 
 })); 
 // Assign the result to the component's data
  }
});

