const callCaseStatusApi = async () => {
  
  // Check if options exist in localStorage
  const cachedOptions = localStorage.getItem('caseStatusOptions');
  if (cachedOptions) {
    component.data.values = JSON.parse(cachedOptions); // Use cached options
    console.log('Using cached faultCategoryOptions');
    return JSON.parse(cachedOptions);
  }
  
  const token = localStorage.getItem('keycloakToken');

  if (!token) {
    console.error('Token not found in localStorage');
    return;
  }
  
    const baseUrl = window.location.hostname.includes('localhost')
    ? 'http://localhost:8081'
    : localStorage.getItem('baseUrl') || '';

  try {
    const response = await fetch(`${baseUrl}/case-definition/case-status`, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`
      }
    });

    if (!response.ok) {
      throw new Error(`API call failed with status: ${response.status}`);
    }

    const data = await response.json();
    const options = data.map(item => ({
      label: item.name,
      value: item.id
    }));

    return options;
  } catch (error) {
    console.error('Error calling the API:', error);
  }
};

callCaseStatusApi().then(options => {
  localStorage.setItem('caseStatusOptions', JSON.stringify(options));
  if (options) {
    component.data.values = options;
    component.defaultValue = '1';
  }
});

